fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    if n == 0 {
        return Vec::new();
    }

    // Preallocate vector with capacity 2*n - 1
    let mut result = Vec::with_capacity(2 * n - 1);

    for (i, &num) in numbers.iter().enumerate() {
        result.push(num);
        // Insert delimiter if not the last element
        if i != n - 1 {
            result.push(delim);
        }
    }

    result
}